@implementation SkyDPad

- (void)trackPoint:(CGPoint)point {
    CGFloat x = point.x - CGRectGetMidX(self.bounds);
    CGFloat y = point.y - CGRectGetMidY(self.bounds);
    CGFloat deadZone = CGRectGetWidth(self.bounds) / 8;
